  }
}

/**
 * Basic tests for the Express.js application
 * Demonstrates validation and error handling
 */

const request = require('supertest');
const app = require('./app');

describe('Health Endpoint', () => {
  test('should return 200 OK', async () => {
    const response = await request(app).get('/health');
    expect(response.status).toBe(200);
    expect(response.body).toHaveProperty('status', 'ok');
    expect(response.body).toHaveProperty('timestamp');
  });
});

describe('Users Endpoint', () => {
  test('should return list of users', async () => {
    const response = await request(app).get('/users');
    expect(response.status).toBe(200);
    expect(response.body).toHaveProperty('users');
    expect(Array.isArray(response.body.users)).toBe(true);
  });

  test('should validate limit parameter', async () => {
    // Test invalid limit
    let response = await request(app).get('/users?limit=0');
    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Invalid limit parameter');

    response = await request(app).get('/users?limit=101');
    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Invalid limit parameter');

    response = await request(app).get('/users?limit=invalid');
    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Invalid limit parameter');

    // Test valid limit
    response = await request(app).get('/users?limit=5');
    expect(response.status).toBe(200);
    expect(response.body.limit).toBe(5);
  });

  test('should validate offset parameter', async () => {
    // Test invalid offset
    let response = await request(app).get('/users?offset=-1');
    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Invalid offset parameter');

    response = await request(app).get('/users?offset=invalid');
    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Invalid offset parameter');

    // Test valid offset
    response = await request(app).get('/users?offset=2');
    expect(response.status).toBe(200);
    expect(response.body.offset).toBe(2);
  });
});

describe('Individual User Endpoint', () => {
  test('should return a user by valid ID', async () => {
    const response = await request(app).get('/users/1');
    expect(response.status).toBe(200);
    expect(response.body).toHaveProperty('id', 1);
    expect(response.body).toHaveProperty('name');
    expect(response.body).toHaveProperty('email');
  });

  test('should return 404 for non-existent user', async () => {
    const response = await request(app).get('/users/999');
    expect(response.status).toBe(404);
    expect(response.body).toHaveProperty('error', 'User not found');
  });

  test('should validate user ID parameter', async () => {
    // Test invalid IDs
    let response = await request(app).get('/users/0');
    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Invalid user ID');

    response = await request(app).get('/users/-1');
    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Invalid user ID');

    response = await request(app).get('/users/abc');
    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Invalid user ID');
  });
});

describe('Rate Limiting', () => {
  test('should apply rate limiting', async () => {
    // Note: This test would need to be adjusted based on actual rate limit settings
    // For demonstration purposes, we're just checking the endpoint works
    const response = await request(app).get('/health');
    expect(response.status).toBe(200);
  });
});

describe('404 Handling', () => {
  test('should return 404 for undefined routes', async () => {
    const response = await request(app).get('/undefined-route');
    expect(response.status).toBe(404);
    expect(response.body).toHaveProperty('error', 'Not found');
  });
});

