  test('should return status ok', async () => {
    const response = await request(app)
      .get('/health')
      .expect(200)
      .expect('Content-Type', /json/);

    expect(response.body.status).toBe('ok');
    expect(response.body).toHaveProperty('timestamp');
  });
});

describe('GET /users', () => {
  test('should return users with default pagination', async () => {
    const response = await request(app)
      .get('/users')
      .expect(200)
      .expect('Content-Type', /json/);

    expect(response.body.status).toBe('success');
    expect(response.body.data.users).toHaveLength(2);
  });

  test('should validate limit parameter', async () => {
    await request(app)
      .get('/users?limit=0')
      .expect(400);

    await request(app)
      .get('/users?limit=101')
      .expect(400);

    await request(app)
      .get('/users?limit=invalid')
      .expect(400);
  });

  test('should validate offset parameter', async () => {
    await request(app)
      .get('/users?offset=-1')
      .expect(400);

    await request(app)
      .get('/users?offset=invalid')
      .expect(400);
  });

  test('should paginate results correctly', async () => {
    const response = await request(app)
      .get('/users?limit=1&offset=0')
      .expect(200);

    expect(response.body.data.users).toHaveLength(1);
    expect(response.body.data.users[0].id).toBe(1);
  });
});

describe('Error handling', () => {
  test('should return 404 for undefined routes', async () => {
    await request(app)
      .get('/undefined-route')
      .expect(404);
  });
});

