const rateLimit = require('express-rate-limit');
const { validate } = require('express-validation');
const Joi = require('joi');

// Security middleware
app.use(helmet());
app.use(express.json());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Validation schemas
const userQuerySchema = {
  query: Joi.object({
    limit: Joi.number().integer().min(1).max(100).default(10),
    offset: Joi.number().integer().min(0).default(0),
    search: Joi.string().max(100).allow('')
  })
};

const userIdSchema = {
  params: Joi.object({
    id: Joi.number().integer().min(1).required()
  })
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: '1.0.0'
    });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with validation
app.get('/users', validate(userQuerySchema), (req, res) => {
  try {
    const { limit, offset, search } = req.query;

    // Sample data - in real app, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      // ... more users
    ];

    // Filter based on search term if provided
    let filteredUsers = users;
    if (search) {
      const searchTerm = search.toLowerCase().trim();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchTerm) ||
        user.email.toLowerCase().includes(searchTerm)
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: filteredUsers.length,
        hasMore: offset + limit < filteredUsers.length
      }
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Example of a user-specific endpoint with validation
app.get('/users/:id', validate(userIdSchema), (req, res) => {
  try {
    const userId = req.params.id;

    // In a real app, fetch user from database
    const user = { id: userId, name: 'Sample User', email: 'user@example.com' };

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (error) {
    console.error('Error in /users/:id endpoint:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  // In production, don't leak detailed error messages
  const statusCode = err.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message || 'Internal server error';

  res.status(statusCode).json({ 
    error: message,
    // Only include error details in development
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
```

