```javascript
// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(urlencoded({ extended: true, limit: '10kb' })); // Limit URL-encoded data
app.use(xss()); // Prevent XSS attacks
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Input validation middleware
const validateUserQuery = (req, res, next) => {
  const { id, name, email } = req.query;

  // Validate ID if provided
  if (id !== undefined) {
    if (!/^\d+$/.test(id)) {
      return res.status(400).json({ 
        error: 'Invalid input', 
        message: 'ID must be a positive integer' 
      });
    }

    // Additional range validation
    const numId = parseInt(id);
    if (numId < 1 || numId > 1000000) {
      return res.status(400).json({ 
        error: 'Invalid input', 
        message: 'ID must be between 1 and 1,000,000' 
      });
    }
  }

  // Validate name if provided
  if (name !== undefined) {
    if (typeof name !== 'string' || name.trim() === '') {
      return res.status(400).json({ 
        error: 'Invalid input', 
        message: 'Name must be a non-empty string' 
      });
    }

    // Limit name length
    if (name.length > 100) {
      return res.status(400).json({ 
        error: 'Invalid input', 
        message: 'Name must not exceed 100 characters' 
      });
    }

    // Basic sanitization (additional to xss-clean)
    if (/[<>\"']/.test(name)) {
      return res.status(400).json({ 
        error: 'Invalid input', 
        message: 'Name contains invalid characters' 
      });
    }
  }

  // Validate email if provided
  if (email !== undefined) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return res.status(400).json({ 
        error: 'Invalid input', 
        message: 'Please provide a valid email address' 
      });
    }

