const request = require('supertest');
const app = require('./app');

describe('Error Handling Tests', () => {
  test('Invalid limit parameter returns 400 error', async () => {
    const response = await request(app)
      .get('/users?limit=invalid')
      .expect(400);

    expect(response.body.status).toBe('fail');
  });

  test('Limit exceeding maximum returns 400 error', async () => {
    const response = await request(app)
      .get('/users?limit=101')
      .expect(400);

    expect(response.body.status).toBe('fail');
  });

  test('Negative offset returns 400 error', async () => {
    const response = await request(app)
      .get('/users?offset=-1')
      .expect(400);

    expect(response.body.status).toBe('fail');
  });

  test('Non-existent route returns 404 error', async () => {
    const response = await request(app)
      .get('/nonexistent')
      .expect(404);

    expect(response.body.status).toBe('fail');
  });

  test('Health endpoint returns 200', async () => {
    const response = await request(app)
      .get('/health')
      .expect(200);

    expect(response.body.status).toBe('ok');
  });

  test('Valid users request returns 200', async () => {
    const response = await request(app)
      .get('/users?limit=2&offset=0')
