// Improved application with enhanced error handling, input validation, and security

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Limit URL-encoded data

// Prevent NoSQL injection and object pollution
app.use(mongoSanitize());
app.use(hpp());

// Prevent XSS attacks
app.use(xss());

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Custom request logger for debugging (remove in production or adjust)
app.use((req, res, next) => {
  console.log(`${req.method} ${req.path} - ${new Date().toISOString()}`);
  next();
});

// Input validation middleware examples
const validateUserId = (req, res, next) => {
  const userId = req.params.id || req.query.id;

  if (userId !== undefined) {
    // Validate that userId is a positive integer
    if (!/^\d+$/.test(userId) || parseInt(userId, 10) <= 0) {
      return res.status(400).json({
        error: 'Validation failed',
        message: 'User ID must be a positive integer'
      });
    }

    // Convert to number for safe usage
    req.validatedUserId = parseInt(userId, 10);
  }

  next();
};

const validatePagination = (req, res, next) => {
  const page = parseInt(req.query.page) || 1;
  const limit = parseInt(req.query.limit) || 10;

  // Validate pagination parameters
  if (page < 1 || limit < 1 || limit > 100) {
    return res.status(400).json({
      error: 'Validation failed',
      message: 'Page must be >= 1 and limit must be between 1 and 100'
    });
  }

  req.pagination = { page, limit };
  next();
};

// Health check endpoint with better error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({
      error: 'Internal server error',
      message: 'Unable to retrieve health status'
    });
  }
});

// Users endpoint with input validation
app.get('/users', validatePagination, (req, res) => {
  try {
    // Mock user data - in real app, this would come from database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply pagination
    const startIndex = (req.pagination.page - 1) * req.pagination.limit;
    const endIndex = startIndex + req.pagination.limit;
    const paginatedUsers = users.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers,
      pagination: {
        page: req.pagination.page,
        limit: req.pagination.limit,
        total: users.length,
        totalPages: Math.ceil(users.length / req.pagination.limit)
      }
    });
  } catch (error) {
    res.status(500).json({
      error: 'Internal server error',
      message: 'Unable to retrieve users'
    });
  }
});

// Example endpoint demonstrating user ID validation
app.get('/users/:id', validateUserId, (req, res) => {
  try {
    // Mock user lookup - in real app, this would query database
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' }
    ];

    const user = mockUsers.find(u => u.id === req.validatedUserId);

    if (!user) {
      return res.status(404).json({
        error: 'Not found',
        message: `User with ID ${req.validatedUserId} not found`
      });
    }

    res.json({ data: user });
  } catch (error) {
    res.status(500).json({
      error: 'Internal server error',
      message: 'Unable to retrieve user'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Determine if we're in production
  const isProduction = process.env.NODE_ENV === 'production';

  // Default error response
  const errorResponse = {
    error: 'Internal server error',
    message: isProduction ? 'An unexpected error occurred' : err.message
  };

  // Add error details in development only
  if (!isProduction && err.stack) {
    errorResponse.stack = err.stack;
  }

  // Set appropriate status code
  const statusCode = err.status || 500;
  res.status(statusCode).json(errorResponse);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Optionally close the server gracefully
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

