const request = require('supertest');
const app = require('./app');

describe('Express App Security Tests', () => {
  let server;

  beforeAll(() => {
    // Use a different port for testing to avoid conflicts
    server = app.listen(3001);
  });

  afterAll(() => {
    server.close();
  });

  describe('Health Endpoint', () => {
    test('should return 200 and status ok', async () => {
      const response = await request(app).get('/health');
      expect(response.status).toBe(200);
      expect(response.body.status).toBe('ok');
      expect(response.body).toHaveProperty('timestamp');
    });
  });

  describe('Users Endpoint', () => {
    test('should return paginated users with default values', async () => {
      const response = await request(app).get('/users');
      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('data');
      expect(response.body).toHaveProperty('pagination');
      expect(response.body.pagination.page).toBe(1);
      expect(response.body.pagination.limit).toBe(10);
    });

    test('should validate page parameter', async () => {
      const response = await request(app).get('/users?page=0');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');
    });

    test('should validate limit parameter', async () => {
      const response = await request(app).get('/users?limit=0');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');
    });

    test('should respect limit maximum', async () => {
      const response = await request(app).get('/users?limit=101');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');
    });

    test('should paginate correctly', async () => {
      const response = await request(app).get('/users?page=1&limit=2');
      expect(response.status).toBe(200);
      expect(response.body.data.length).toBe(2);
      expect(response.body.pagination.total).toBe(5);
      expect(response.body.pagination.totalPages).toBe(3);
    });
  });

  describe('User ID Validation', () => {
    test('should validate user ID as positive integer', async () => {
      const response = await request(app).get('/users/-1');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');
    });

    test('should reject non-numeric user ID', async () => {
      const response = await request(app).get('/users/abc');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');
    });

    test('should return 404 for non-existent user', async () => {
      const response = await request(app).get('/users/999');
      expect(response.status).toBe(404);
      expect(response.body.error).toBe('Not found');
    });

    test('should return user for valid ID', async () => {
      const response = await request(app).get('/users/1');
      expect(response.status).toBe(200);
      expect(response.body.data.id).toBe(1);
      expect(response.body.data.name).toBe('Alice');
    });
  });

  describe('404 Handling', () => {
    test('should return 404 for undefined routes', async () => {
      const response = await request(app).get('/undefined-route');
      expect(response.status).toBe(404);
      expect(response.body.error).toBe('Not found');
    });
  });

  describe('Security Headers', () => {
    test('should set helmet headers', async () => {
      const response = await request(app).get('/health');
      // Check for some common helmet headers
      expect(response.headers).toHaveProperty('x-content-type-options');
      expect(response.headers['x-content-type-options']).toBe('nosniff');
      expect(response.headers).toHaveProperty('x-frame-options');
    });
  });
});

